import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import cp from 'node:child_process';import {chromium} from 'playwright-core';
const CONTRACT_PATH='pls_v16/BINDING_CONTRACT.json',CONTRACT_SHA='6e8558b4545c1084b3a8342eb2f66611de97dc2e78db46f60919666313164140';
const META_SHA='25d1032044996d2eed8cab3b2c9d6bfbfab91349f0ac6e49ef168c307654b24f',MASK_SHA='8935332736286b4b8238966e7a12ee2049d5fab0816a666061db7cb2c9ee56b0';
const SHARD_COUNT=Number(process.env.PLS_V16_SHARD_COUNT||8),SHARD_INDEX=Number(process.env.PLS_V16_SHARD_INDEX),OUT=process.env.PLS_V16_SHARD_OUT||'wip-pls-v16-vector-shards',PORT=Number(process.env.PLS_V16_SHARD_PORT||8768);
const ok=(c,m)=>{if(!c)throw new Error(m);},sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
ok(Number.isInteger(SHARD_COUNT)&&SHARD_COUNT>=2&&SHARD_COUNT<=32,'SHARD_COUNT');ok(Number.isInteger(SHARD_INDEX)&&SHARD_INDEX>=0&&SHARD_INDEX<SHARD_COUNT,'SHARD_INDEX');fs.mkdirSync(OUT,{recursive:true});
ok(sha(CONTRACT_PATH)===CONTRACT_SHA,'BINDING_CONTRACT_SHA');const C=JSON.parse(fs.readFileSync(CONTRACT_PATH,'utf8'));
for(const f of [...C.model.tokenizer_and_config_files,...C.model.delivery.parts,...C.runtime.files]){ok(fs.existsSync(f.path),'SUPPORT_MISSING '+f.path);ok(fs.statSync(f.path).size===Number(f.bytes),'SUPPORT_SIZE '+f.path);ok(sha(f.path)===f.sha256,'SUPPORT_HASH '+f.path);}
cp.execFileSync(process.execPath,['.github/wip-semantic-current-pack-build.cjs'],{stdio:['ignore','pipe','inherit'],maxBuffer:32*1024*1024});
const META='wip-current-semantic-pack/metadata.jsonl',MASK='wip-current-semantic-pack/jesus_mask.bits';ok(sha(META)===META_SHA,'METADATA_HASH');ok(sha(MASK)===MASK_SHA,'MASK_HASH');const rows=fs.readFileSync(META,'utf8').trimEnd().split(/\r?\n/).filter(Boolean).map(JSON.parse);ok(rows.length===C.chunker.expected_passages,'PASSAGE_COUNT');
const start=Math.floor(rows.length*SHARD_INDEX/SHARD_COUNT),end=Math.floor(rows.length*(SHARD_INDEX+1)/SHARD_COUNT);ok(end>start,'EMPTY_SHARD');
const root='/tmp/ldc-pls-v16-shard-'+SHARD_INDEX,modelDir=path.join(root,'model'),onnxDir=path.join(modelDir,'onnx'),runtimeDir=path.join(root,'runtime');fs.rmSync(root,{recursive:true,force:true});fs.mkdirSync(onnxDir,{recursive:true});fs.mkdirSync(runtimeDir,{recursive:true});
for(const f of C.model.tokenizer_and_config_files)fs.copyFileSync(f.path,path.join(modelDir,path.basename(f.path)));for(const f of C.runtime.files)fs.copyFileSync(f.path,path.join(runtimeDir,path.basename(f.path)));
const joined=Buffer.concat(C.model.delivery.parts.map(x=>fs.readFileSync(x.path)));ok(joined.length===C.model.delivery.original_model_bytes,'MODEL_BYTES');ok(hash(joined)===C.model.model_sha256,'MODEL_HASH');fs.writeFileSync(path.join(onnxDir,'model_int8.onnx'),joined);fs.copyFileSync('.github/wip-semantic-v16-vector-build-browser.html',path.join(root,'builder.html'));
const server=cp.spawn('python3',['-m','http.server',String(PORT),'--bind','127.0.0.1'],{cwd:root,stdio:['ignore','ignore','inherit']});let browser=null;const t0=Date.now();
try{
 await new Promise(r=>setTimeout(r,900));const exe=process.env.CHROME_PATH||'/usr/bin/google-chrome';ok(fs.existsSync(exe),'CHROME_NOT_FOUND');browser=await chromium.launch({headless:true,executablePath:exe,args:['--no-sandbox']});const page=await browser.newPage();page.setDefaultTimeout(180000);await page.goto('http://127.0.0.1:'+PORT+'/builder.html',{waitUntil:'load'});await page.waitForFunction(()=>document.querySelector('#status')?.textContent==='module-ready');await page.evaluate(()=>window.initModel());await page.waitForFunction(()=>document.querySelector('#status')?.textContent==='ready');
 const probeText=String(rows[start].text||''),[p1]=await page.evaluate(async t=>await window.embedQuantizedBatch([t]),probeText),[p2]=await page.evaluate(async t=>await window.embedQuantizedBatch([t]),probeText);ok(JSON.stringify(p1)===JSON.stringify(p2),'SHARD_REPEAT_DETERMINISM');
 const dim=C.model.embedding_dim,count=end-start,vectors=Buffer.alloc(count*dim),norms=Buffer.alloc(count*4);
 for(let row=start;row<end;row++){const [z]=await page.evaluate(async t=>await window.embedQuantizedBatch([t]),String(rows[row].text||''));ok(z.q.length===dim,'VECTOR_DIM');const local=row-start;for(let j=0;j<dim;j++)vectors.writeInt8(Number(z.q[j]),local*dim+j);norms.writeFloatLE(Number(z.inv),local*4);if((row-start)%100===0)console.log(JSON.stringify({phase:'shard',shard:SHARD_INDEX,completed:row-start+1,total:count,elapsed_s:Math.round((Date.now()-t0)/1000)}));}
 const tag=SHARD_INDEX+'-of-'+SHARD_COUNT,vec=path.join(OUT,'vectors.part-'+tag+'.i8'),inv=path.join(OUT,'inverse_norms.part-'+tag+'.f32le');fs.writeFileSync(vec,vectors);fs.writeFileSync(inv,norms);
 const report={schema:'ldc-pls-v16-vector-shard-v1',status:'ENGINEERING_ONLY',binding_contract_sha256:CONTRACT_SHA,pack_id:C.pack_id,shard_index:SHARD_INDEX,shard_count:SHARD_COUNT,start_row:start,end_row_exclusive:end,row_count:count,first_passage_id:rows[start].passage_id,last_passage_id:rows[end-1].passage_id,metadata_sha256:META_SHA,jesus_mask_sha256:MASK_SHA,model_sha256:C.model.model_sha256,backend:'BROWSER_WASM_PINNED_SINGLETON',repeat_determinism:true,vectors:{bytes:vectors.length,sha256:sha(vec)},inverse_norms:{bytes:norms.length,sha256:sha(inv)},elapsed_seconds:Math.round((Date.now()-t0)/1000)};
 fs.writeFileSync(path.join(OUT,'shard-'+tag+'.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
}finally{if(browser)await browser.close().catch(()=>{});server.kill('SIGTERM');}
